def _collect_retrieval_uris(node: Any) -> list[tuple[str, float | None]]:
    found: dict[str, float | None] = {}

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            uri = value.get("uri")
            if isinstance(uri, str) and uri.startswith("viking://"):
                score = value.get("score")
                try:
                    parsed_score = float(score) if score is not None else None
                except (TypeError, ValueError):
                    parsed_score = None
                found.setdefault(uri, parsed_score)
            for item in value.values():
                walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    walk(node)
    return list(found.items())


def _set_retrieval_state(http_request: Request, result: Any, count: int) -> None:
    http_request.state.retrieval_result_count = count
    pairs = _collect_retrieval_uris(result)
    http_request.state.retrieval_result_uris = [uri for uri, _ in pairs]
    http_request.state.retrieval_result_scores = [score for _, score in pairs]

